public class Main {
    public static void main(String[] args) {
        int passingCount = 0; // Counter
        int totalMarks = 0;   // Accumulator

        // Simulating exam marks for 5 students
        int[] scores = {85, 42, 90, 38, 75};

        for (int i = 0; i < scores.length; i++) {
            totalMarks += scores[i];
            if (scores[i] >= 50) {
                passingCount++;
            }
        }

        double classAverage = (double) totalMarks / scores.length;

        System.out.println("Total Students: " + scores.length);
        System.out.println("Passing Students: " + passingCount);
        System.out.println("Total Class Marks: " + totalMarks);
        System.out.printf("Class Average: %.1f%n", classAverage);
    }
}

