public class Main {
    public static void main(String[] args) {
        int[] prices = {120, 45, 250, 85};
        int total = 0;
        int expensiveCount = 0;

        for (int i = 0; i < prices.length; i++) {
            total += prices[i];
            if (prices[i] > 100) {
                expensiveCount++;
            }
        }

        double avg = (double) total / prices.length;
        System.out.println("Total Bill: $" + total);
        System.out.println("Expensive Items (>100): " + expensiveCount);
        System.out.printf("Average Item Price: $%.2f%n", avg);
    }
}

